// Keep native SVG strings identical to the reviewable SVG files. No transformer required.
const fs = require('node:fs');
const names = { logo: 'logo', logoCompact: 'logo-compact', apple: 'apple', worldMap: 'world-map' };
const output = Object.entries(names)
  .map(
    ([key, file]) =>
      `export const ${key} = ${JSON.stringify(fs.readFileSync(`assets/brand/${file}.svg`, 'utf8'))};`,
  )
  .join('\n');
fs.writeFileSync(
  'src/theme/svg-assets.ts',
  '// Generated by scripts/generate-svg-assets.cjs; edit assets/brand/*.svg.\n' + output + '\n',
);
